def analyze_pairs(inputs, outputs):
    """Analyze the input/output pairs to understand transformations"""
    for i, (inp, out) in enumerate(zip(inputs, outputs)):
        print(f"Input {i}: '{inp}' -> Output {i}: '{out}'")
        # Show character-by-character differences
        min_len = min(len(inp), len(out))
        for j in range(min_len):
            if inp[j] != out[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{out[j]}'")
        if len(inp) != len(out):
            print(f"  Length change: {len(inp)} -> {len(out)}")

inputs = ['jw', 'dac', 'iiucck', 'hfcg', 'auz']
outputs = ['jw', 'dag', 'iiuxhuk', 'hwxbzgg', 'auz']
analyze_pairs(inputs, outputs)

